var n=`0937-onigiri`;var s=`world-0937`;var t=`JP`;var a=`east-asia`;var r=8;var o=50;var d={en:`Onigiri`,ua:`Оніґірі`};var g={en:`Onigiri is a Japan dish made with sushi rice, rice vinegar, canned tuna, mayonnaise. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Оніґірі, страва кухні країни Японія. Основні складники: рис для суші, рисовий оцет, консервований тунець, майонез. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var l=[{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 25 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 25 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:25,i:[[`sushi-rice`,420,`g`],[`water`,475,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`table-salt`,7,`g`],[`rice-vinegar`,20,`ml`]]},{en:`With wet salted hands mold warm sushi rice around the seasoned tuna filling into triangles, then attach nori strips.`,ua:`Зволоженими підсоленими руками сформуйте трикутники з теплого рису навколо тунцевої начинки й прикріпіть смужки норі.`,t:[`molding-food`],m:15,i:[[`canned-tuna`,190,`g`],[`mayonnaise`,55,`g`],[`nori`,5,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`white-sesame-seeds`,18,`g`]]}];var h={slug:n,id:s,country:`JP`,region:a,servings:8,minutes:50,title:d,text:g,steps:l};export{t as country,h as default,s as id,o as minutes,a as region,r as servings,n as slug,l as steps,g as text,d as title};